SZGame3D.runProject(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame3D.restart());
  // Ao iniciar
  const cena = SZGame3D.createFullscreenScene("#94d5f5");
  SZGame3D.setCameraPosition(cena, 0, 12, 21);
  SZGame3D.setFOV(cena, 48);
  SZGame3D.addAmbientLight(cena, "#ffffff", 0.65);
  const mar = SZGame3D.createModelFile(cena, "ilha-mar", 80);
  SZGame3D.setPosition(mar, 0, -0.4, 0);
  const terreno = SZGame3D.createModelFile(cena, "ilha-terreno", 21.7);
  SZGame3D.setPosition(terreno, -3.15, -0.11124999910593034, 0);
  const ponte = SZGame3D.createModelFile(cena, "ilha-ponte", 2.2000000059604643);
  SZGame3D.setPosition(ponte, 2.575, 0.35, 0.75);
  const coqueiroTras = SZGame3D.createModelFile(cena, "ilha-coqueiro-tras", 3.390589635214912);
  SZGame3D.setPosition(coqueiroTras, -7.1568312537535546, 1.2526776879515462, -4.2);
  const coqueiroFrente = SZGame3D.createModelFile(cena, "ilha-coqueiro-tras", 3.249315067080957);
  SZGame3D.setPosition(coqueiroFrente, -6.750296618180489, 1.2004827842868981, 4.5);
  const vegetacao = SZGame3D.createModelFile(cena, "ilha-vegetacao", 9.503074318546656);
  SZGame3D.setPosition(vegetacao, -1.5670287587114384, 0.21999999999999997, -0.09999999999999964);
  const farol = SZGame3D.createModelFile(cena, "ilha-farol-apagado", 5.359999976158143);
  SZGame3D.setPosition(farol, 5.2, 2.680000011920929, 0.1);
  const farolAceso = SZGame3D.createModelFile(cena, "ilha-farol-aceso", 7.9200000166893005);
  SZGame3D.setPosition(farolAceso, 5.2, 2.680000011920929, 3.13999999165535);
  SZGame3D.setVisible(farolAceso, "hide");
  const barco = SZGame3D.createModelFile(cena, "ilha-veleiro", 3.1612625531613077);
  SZGame3D.setPosition(barco, 8.652660034712952, 1.059999976158142, 4.500745585792692);
  const pedra = SZGame3D.createModelFile(cena, "ilha-pedras", 2.8600635164447805);
  SZGame3D.setPosition(pedra, -2.0581945798776595, 1.366270815065906, -0.9617974009132754);
  const personagem = SZGame3D.createModelFile(cena, "ilha-aventureiro", 1.5799999991059304);
  SZGame3D.setPosition(personagem, -6.5, 0.8, 0.75);
  const chave = SZGame3D.createModelFile(cena, "ilha-chave", 0.9059837580290622);
  SZGame3D.setPosition(chave, -3, 1, -2);
  const centro = SZGame3D.createModel(cena);
  SZGame3D.setPosition(centro, -1, 0, 0);
  SZGame3D.cameraLookAt(cena, centro);
  const chaves = SZGame3D.createGroup();
  chaves.push(chave);
  const portas = SZGame3D.createGroup();
  portas.push(farol);
  const jogadores = SZGame3D.createGroup();
  jogadores.push(personagem);
  let ganhou = false;
  let aviso = "Encontre a chave e leve o personagem até o farol.";
  let temChave = false;
  let antesX = -6.5;
  let antesZ = 0.75;
  SZGame3D.hudText("bottom-center", "Setas ou WASD: andar. R: recomeçar.");
  // Quando acontecer
  SZGame3D.onKey("KeyR", () => {
    SZGame3D.restart();
  });
  SZGame3D.onTouchGroup(personagem, chaves, (item) => {
    SZGame3D.setVisible(chave, "hide");
    temChave = true;
    aviso = "Você pegou a chave! Agora vá ao farol.";
  });
  SZGame3D.onTouchGroup(personagem, portas, (item) => {
    if (temChave) {
      SZGame3D.setVisible(farol, "hide");
      SZGame3D.setVisible(farolAceso, "show");
      ganhou = true;
      aviso = "Você acendeu o farol! O barco pode chegar.";
    } else {
      aviso = "Falta a chave. Procure na ilha antes de voltar.";
    }
  });
  // Enquanto estiver rodando
  SZGame3D.animate(cena, () => {
    SZGame3D.controlWithKeys(personagem, 4);
    SZGame3D.updateGroupNoGravity(jogadores);
    if (!(SZGame3D.objectValue(personagem, "x") >= -11 && SZGame3D.objectValue(personagem, "x") <= 0.6 && SZGame3D.objectValue(personagem, "z") >= -5 && SZGame3D.objectValue(personagem, "z") <= 5 || SZGame3D.objectValue(personagem, "x") >= 0.6 && SZGame3D.objectValue(personagem, "x") <= 4 && SZGame3D.objectValue(personagem, "z") >= 0.4 && SZGame3D.objectValue(personagem, "z") <= 1.1 || SZGame3D.objectValue(personagem, "x") >= 4 && SZGame3D.objectValue(personagem, "x") <= 6.1 && SZGame3D.objectValue(personagem, "z") >= -0.5 && SZGame3D.objectValue(personagem, "z") <= 1.7)) {
      SZGame3D.setPosition(personagem, antesX, 0.8, antesZ);
      SZGame3D.setVelocity(personagem, 0, 0, 0);
    } else {
      antesX = SZGame3D.objectValue(personagem, "x");
      antesZ = SZGame3D.objectValue(personagem, "z");
    }
    SZGame3D.hudText("top-center", aviso);
    if (ganhou) {
      SZGame3D.moveTowards(barco, 6.6, -0.1, 4.5, 1.8);
    }
  });
});

